package net.ronm19.phantomism.entity.ai;

import java.lang.ref.WeakReference;
import java.util.*;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.tags.DamageTypeTags;
import net.minecraft.world.damagesource.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.entity.projectile.arrow.AbstractArrow;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.*;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.*;
import net.neoforged.neoforge.event.entity.living.*;
import net.ronm19.phantomism.Phantomism;
import net.ronm19.phantomism.entity.CrystalPhantom;
import net.ronm19.phantomism.vfx.CrystalVfx;

@EventBusSubscriber(modid=Phantomism.MOD_ID)
public final class CrystalDefense {
    private static final Identifier ARMOR=Identifier.fromNamespaceAndPath(Phantomism.MOD_ID,"crystal_fracture"),SLOW=Identifier.fromNamespaceAndPath(Phantomism.MOD_ID,"crystal_refraction_slow"),WEAK=Identifier.fromNamespaceAndPath(Phantomism.MOD_ID,"crystal_refraction_weak");
    private static final String REFLECTED="phantomismCrystalReflected", SESSION="phantomismCrystalSession", UNTIL="phantomismCrystalUntil";
    private record Lease(WeakReference<CrystalPhantom> source,UUID session,long until) {}
    private static final Map<LivingEntity,Lease> FRACTURES=new WeakHashMap<>(),CONTROLS=new WeakHashMap<>();
    private static final Map<CrystalPhantom,Long> RETALIATIONS=new WeakHashMap<>();
    private static final ThreadLocal<Boolean> REFLECTING=ThreadLocal.withInitial(()->false);
    private CrystalDefense(){}
    public static boolean reflecting(){return REFLECTING.get();}
    private static boolean live(LivingEntity target,Lease lease){CrystalPhantom source=lease.source().get();return source!=null&&source.enabled()&&source.session().equals(lease.session())&&source.level()==target.level()&&source.validTarget(target)&&source.distanceToSqr(target)<=48*48&&target.level().getGameTime()<lease.until();}
    private static void remove(LivingEntity target,Identifier identifier,net.minecraft.core.Holder<Attribute> attribute){AttributeInstance instance=target.getAttribute(attribute);if(instance!=null){instance.removeModifier(identifier);}}
    private static void clearControl(LivingEntity target){remove(target,SLOW,Attributes.MOVEMENT_SPEED);remove(target,WEAK,Attributes.ATTACK_DAMAGE);}
    public static void maintain(){FRACTURES.entrySet().removeIf(entry->{if(live(entry.getKey(),entry.getValue())){return false;}remove(entry.getKey(),ARMOR,Attributes.ARMOR);return true;});CONTROLS.entrySet().removeIf(entry->{if(live(entry.getKey(),entry.getValue())){return false;}clearControl(entry.getKey());return true;});RETALIATIONS.entrySet().removeIf(entry->!entry.getKey().enabled()||entry.getKey().level().getGameTime()>=entry.getValue());}
    private static boolean claim(Map<LivingEntity,Lease> leases,CrystalPhantom source,LivingEntity target,int duration){maintain();if(!source.enabled()||!source.validTarget(target)||source.distanceToSqr(target)>48*48||target instanceof OwnableEntity||target instanceof net.minecraft.world.entity.player.Player||PhantomDuels.pair(source,target)||leases.size()>=256&&!leases.containsKey(target)){return false;}Lease previous=leases.get(target);if(previous!=null&&previous.source().get()!=source){return false;}leases.put(target,new Lease(new WeakReference<>(source),source.session(),source.level().getGameTime()+Math.clamp(duration,1,60)));return true;}
    public static void fracture(CrystalPhantom source,LivingEntity target,int duration){if(claim(FRACTURES,source,target,duration)){AttributeInstance armor=target.getAttribute(Attributes.ARMOR);if(armor!=null){armor.removeModifier(ARMOR);armor.addTransientModifier(new AttributeModifier(ARMOR,-2,AttributeModifier.Operation.ADD_VALUE));}}}
    public static void control(CrystalPhantom source,LivingEntity target,int duration){if(!claim(CONTROLS,source,target,duration)){return;}clearControl(target);if(target instanceof Mob mob&&!GravityControl.movementImmune(mob)){AttributeInstance speed=target.getAttribute(Attributes.MOVEMENT_SPEED);if(speed!=null){speed.addTransientModifier(new AttributeModifier(SLOW,-.15D,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));}}AttributeInstance attack=target.getAttribute(Attributes.ATTACK_DAMAGE);if(attack!=null){attack.addTransientModifier(new AttributeModifier(WEAK,target instanceof Mob mob&&GravityControl.movementImmune(mob)?-.05D:-.1D,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));}}
    public static void push(CrystalPhantom source,LivingEntity target,double amount){if(!(target instanceof Mob mob)||!source.validTarget(target)||GravityControl.movementImmune(mob)||target.isPassenger()||target.isVehicle()){return;}Vec3 away=target.position().subtract(source.position()).multiply(1,0,1).normalize();if(away.lengthSqr()>.001D){mob.knockback(amount,-away.x,-away.z,source.damageSources().mobAttack(source),0);}}
    private static boolean accepts(CrystalPhantom source,LivingEntity attacker,LivingEntity ward){return source.enabled()&&source.recipient(ward)&&source.validTarget(attacker)&&(!PhantomDuels.pair(ward,attacker)||ward==source)&&!PhantomDuels.excludesObserver(source,attacker);}
    public static boolean reflected(Projectile projectile){return projectile.getPersistentData().getBooleanOr(REFLECTED,false);}
    public static boolean reflect(CrystalPhantom source,Projectile projectile,LivingEntity ward,boolean force){if(!(projectile.getOwner() instanceof LivingEntity attacker)||!accepts(source,attacker,ward)||!source.reflective(ward)||!source.canReflect()||!GolemDefense.ordinary(projectile)||reflected(projectile)||!source.line(source.getEyePosition(),projectile.position())||!source.line(projectile.position(),attacker.getEyePosition())||!force&&source.getRandom().nextFloat()>=.2F){return false;}Vec3 aim=attacker.getEyePosition().subtract(projectile.position());if(!Double.isFinite(aim.lengthSqr())||aim.lengthSqr()<.01D){return false;}float speed=(float)Math.clamp(projectile.getDeltaMovement().length()*.8D,.5D,1.6D);projectile.getPersistentData().putBoolean(REFLECTED,true);projectile.getPersistentData().putString(SESSION,source.session().toString());projectile.getPersistentData().putLong(UNTIL,source.level().getGameTime()+100);projectile.setOwner(source);projectile.clearFire();projectile.shoot(aim.x,aim.y,aim.z,speed,0);projectile.needsSync=true;if(projectile instanceof AbstractArrow arrow){arrow.setBaseDamage(.75D);arrow.setCritArrow(false);arrow.pickup=AbstractArrow.Pickup.DISALLOWED;}source.commitReflection();CrystalVfx.emit(source,CrystalVfx.REFLECT,projectile,projectile.position(),aim.normalize(),18,2);return true;}
    public static void intercept(CrystalPhantom source,ServerLevel level){if(!source.enabled()||!source.canReflect()){return;}double range=source.domainTicks()>0?18:source.barrierTicks()>0?12:4;Vec3 center=source.domainTicks()>0?source.domainCenter():source.position();if(center==null){return;}var wards=level.getEntitiesOfClass(LivingEntity.class,new AABB(center,center).inflate(range),source::reflective).stream().filter(ward->ward.position().distanceToSqr(center)<=range*range).limit(16).toList();for(Projectile projectile:level.getEntitiesOfClass(Projectile.class,new AABB(center,center).inflate(range),projectile->GolemDefense.ordinary(projectile)&&!reflected(projectile)&&projectile.getOwner() instanceof LivingEntity attacker&&source.validTarget(attacker)).stream().limit(24).toList()){if(!source.canReflect()){break;}Vec3 motion=projectile.getDeltaMovement();if(motion.lengthSqr()<.01D){continue;}LivingEntity ward=wards.stream().filter(target->target.getBoundingBox().inflate(.5D).clip(projectile.position(),projectile.position().add(motion.scale(6))).isPresent()&&source.line(source.getEyePosition(),target.getEyePosition())).findFirst().orElse(null);if(ward!=null){reflect(source,projectile,ward,source.barrierTicks()>0||source.domainTicks()>0||source.shellTicks()>0);}}}
    private static boolean validReflection(Projectile projectile){return projectile.getOwner() instanceof CrystalPhantom source&&source.enabled()&&projectile.getPersistentData().getStringOr(SESSION,"").equals(source.session().toString())&&projectile.level().getGameTime()<projectile.getPersistentData().getLongOr(UNTIL,0);}
    @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.EntityTickEvent.Post event){if(event.getEntity() instanceof Projectile projectile&&!projectile.level().isClientSide()&&reflected(projectile)&&!validReflection(projectile)){projectile.discard();}}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void impact(ProjectileImpactEvent event){Projectile projectile=event.getProjectile();if(!reflected(projectile)||!(event.getRayTraceResult() instanceof EntityHitResult hit)){return;}if(!validReflection(projectile)||!(projectile.getOwner() instanceof CrystalPhantom source)||!(hit.getEntity() instanceof LivingEntity victim)||!source.validTarget(victim)){event.setCanceled(true);projectile.discard();}}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void incoming(LivingIncomingDamageEvent event){if(!(event.getEntity().level() instanceof ServerLevel)||!(event.getSource().getDirectEntity() instanceof Projectile projectile)||!reflected(projectile)){return;}if(!validReflection(projectile)||!(projectile.getOwner() instanceof CrystalPhantom source)||!source.validTarget(event.getEntity())){event.setCanceled(true);projectile.discard();}else{event.setAmount(Math.min(4,event.getAmount()));}}
    private static boolean ranged(DamageSource damage){return damage.is(DamageTypeTags.IS_PROJECTILE)||damage.getDirectEntity() instanceof Projectile||damage.is(DamageTypes.MAGIC)||damage.is(DamageTypes.INDIRECT_MAGIC);}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void damage(LivingDamageEvent.Pre event){LivingEntity ward=event.getEntity();float incoming=event.getNewDamage();if(!(ward.level() instanceof ServerLevel level)||!Float.isFinite(incoming)||incoming<=0||event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY)||event.getSource().is(DamageTypeTags.BYPASSES_RESISTANCE)){return;}LivingEntity attacker=event.getSource().getEntity() instanceof LivingEntity living?living:null;var candidates=level.getEntitiesOfClass(CrystalPhantom.class,ward.getBoundingBox().inflate(36),source->source.enabled()&&source.recipient(ward)&&(attacker==null||accepts(source,attacker,ward))&&source.line(source.getEyePosition(),ward.getEyePosition())).stream().sorted(Comparator.comparingDouble((CrystalPhantom source)->-source.mitigation(ward)*1000+source.distanceToSqr(ward))).limit(8).toList();if(candidates.isEmpty()){return;}CrystalPhantom source=candidates.getFirst();if(ward==source&&attacker!=null&&!reflecting()){source.shell(level,attacker,incoming);}float reduction=source.mitigation(ward);if(ward==source&&ranged(event.getSource())){reduction=Math.max(reduction,.25F);}if(reduction>0){event.setNewDamage(Math.max(Math.min(incoming,event.getOriginalDamage()*.4F),incoming*(1-reduction)));CrystalVfx.emit(source,CrystalVfx.SHIELD_HIT,ward,ward.getBoundingBox().getCenter(),Vec3.ZERO,12,1.5F);}if(attacker!=null&&!reflecting()&&source.validTarget(attacker)&&source.reflective(ward)&&source.distanceToSqr(attacker)<=18*18&&source.line(source.getEyePosition(),attacker.getEyePosition())&&RETALIATIONS.getOrDefault(source,Long.MIN_VALUE)<=level.getGameTime()&&(ward==source&&source.retaliation()>0||ranged(event.getSource())&&source.getRandom().nextFloat()<.2F)){RETALIATIONS.put(source,level.getGameTime()+20);float returned=Math.min(4,incoming*Math.max(.2F,source.retaliation()));REFLECTING.set(true);try{source.damage(level,attacker,source.damageSources().indirectMagic(source,source),returned);}finally{REFLECTING.set(false);}CrystalVfx.emit(source,CrystalVfx.REFLECT,null,ward.getEyePosition(),attacker.getEyePosition().subtract(ward.getEyePosition()),16,2);}}
    @SubscribeEvent public static void damaged(LivingDamageEvent.Post event){if(event.getEntity() instanceof CrystalPhantom source&&source.level() instanceof ServerLevel&&event.getSource().getEntity() instanceof LivingEntity attacker&&!event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY)){source.storedImpact(attacker,event.getHealthDamage());}}
    public static void releaseControl(CrystalPhantom source){CONTROLS.entrySet().removeIf(entry->{if(entry.getValue().source().get()!=source){return false;}clearControl(entry.getKey());return true;});}
    public static void release(CrystalPhantom source){releaseControl(source);FRACTURES.entrySet().removeIf(entry->{if(entry.getValue().source().get()!=source){return false;}remove(entry.getKey(),ARMOR,Attributes.ARMOR);return true;});RETALIATIONS.remove(source);}
    @SubscribeEvent public static void leave(EntityLeaveLevelEvent event){if(event.getLevel().isClientSide()){return;}if(event.getEntity() instanceof CrystalPhantom source){source.endCrystal();}if(event.getEntity() instanceof LivingEntity target){FRACTURES.remove(target);CONTROLS.remove(target);remove(target,ARMOR,Attributes.ARMOR);clearControl(target);}}
}
